#define _XOPEN_SOURCE 600
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <errno.h>
#include <string.h>
#include <termios.h>
#include <sys/wait.h>
#include <sys/stat.h>

/* 子进程：按路径打开 slave，读取到 EOF/EIO，把读到的内容写 stdout 管道 */
static void child(const char* name, int outfd) {
    int fd = open(name, O_RDONLY | O_NOCTTY);
    if (fd < 0) { _exit(10); }
    /* 通知父进程已打开 */
    char c = 'o'; write(outfd, &c, 1);
    char buf[4096];
    for (;;) {
        ssize_t n = read(fd, buf, sizeof buf);
        if (n > 0) { write(outfd, buf, n); continue; }
        if (n == 0) { const char* e = "EOF0\n"; write(outfd, e, 5); break; }
        const char* e = "EIO\n"; write(outfd, e, 4); break;
    }
    _exit(0);
}

static void run(int raw, const char* label) {
    int m = posix_openpt(O_RDWR | O_NOCTTY);
    grantpt(m); unlockpt(m);
    const char* name = ptsname(m);
    if (raw) {
        struct termios tio; tcgetattr(m, &tio);
        cfmakeraw(&tio); tcsetattr(m, TCSANOW, &tio);
    }
    const char* data = raw ? "PARTIAL123" : "PARTIAL123\n";
    write(m, data, strlen(data));

    int p[2]; pipe(p);
    pid_t pid = fork();
    if (pid == 0) { close(p[0]); child(name, p[1]); }
    close(p[1]);
    char ack; read(p[0], &ack, 1);   /* 等子进程打开 slave */
    usleep(50000);
    close(m);                        /* 子进程已打开后关闭 master */
    char buf[8192]; ssize_t total = 0; ssize_t n;
    while ((n = read(p[0], buf + total, sizeof buf - total)) > 0) total += n;
    int st; waitpid(pid, &st, 0);
    fprintf(stderr, "[%s] child status=0x%x delivered=%.*s\n",
            label, st, (int)total, buf);
    close(p[0]);
}
int main(void) {
    run(0, "canonical+newline");
    run(1, "raw");
    return 0;
}
