/*
 * 测试专用故障注入（非生产代码），经 LD_PRELOAD 加载。
 * 仅在环境变量精确指定路径时激活，其他访问全部透传；不设变量时零影响。
 *
 * BRANCHAUDIT_TEST_OPEN_FAIL=<path>：打开该路径 -> -1/EACCES
 * BRANCHAUDIT_TEST_READ_FAIL=<path>：该路径可正常打开与读取，内容正常
 *   交付，直到真实读取返回 0（正常 EOF）时改为 -1/EIO —— 已取得部分
 *   内容、继续读取时出错，不得被当作正常结束。
 */

#define FD_CAP 4096
static int read_fail_fd[FD_CAP];

static int (*real_open)(const char *, int, ...);
static int (*real_openat)(int, const char *, int, ...);
static ssize_t (*real_read)(int, void *, size_t);
static int (*real_close)(int);

static const char *open_fail_path(void) {
    return getenv("BRANCHAUDIT_TEST_OPEN_FAIL");
}
static const char *read_fail_path(void) {
    return getenv("BRANCHAUDIT_TEST_READ_FAIL");
}

static void remember_fd(int fd, const char *path) {
    const char *target = read_fail_path();
    if (fd >= 0 && fd < FD_CAP && target && path && strcmp(path, target) == 0)
        read_fail_fd[fd] = 1;
}

static int do_open(const char *path, int flags, mode_t mode) {
    if (!real_open) real_open = dlsym(RTLD_NEXT, "open");
    const char *of = open_fail_path();
    if (of && path && strcmp(path, of) == 0) { errno = EACCES; return -1; }
    int fd = real_open(path, flags, mode);
    remember_fd(fd, path);
    return fd;
}

static int do_openat(int dirfd, const char *path, int flags, mode_t mode) {
    if (!real_openat) real_openat = dlsym(RTLD_NEXT, "openat");
    const char *of = open_fail_path();
    if (of && path && strcmp(path, of) == 0) { errno = EACCES; return -1; }
    int fd = real_openat(dirfd, path, flags, mode);
    remember_fd(fd, path);
    return fd;
}

int open(const char *path, int flags, ...) {
    mode_t mode = 0;
    if (flags & O_CREAT) {
        va_list ap; va_start(ap, flags);
        mode = va_arg(ap, mode_t);
        va_end(ap);
    }
    return do_open(path, flags, mode);
}

int open64(const char *path, int flags, ...) {
    mode_t mode = 0;
    if (flags & O_CREAT) {
        va_list ap; va_start(ap, flags);
        mode = va_arg(ap, mode_t);
        va_end(ap);
    }
    return do_open(path, flags, mode);
}

int openat(int dirfd, const char *path, int flags, ...) {
    mode_t mode = 0;
    if (flags & O_CREAT) {
        va_list ap; va_start(ap, flags);
        mode = va_arg(ap, mode_t);
        va_end(ap);
    }
    return do_openat(dirfd, path, flags, mode);
}

int openat64(int dirfd, const char *path, int flags, ...) {
    mode_t mode = 0;
    if (flags & O_CREAT) {
        va_list ap; va_start(ap, flags);
        mode = va_arg(ap, mode_t);
        va_end(ap);
    }
    return do_openat(dirfd, path, flags, mode);
}

ssize_t read(int fd, void *buf, size_t n) {
    if (!real_read) real_read = dlsym(RTLD_NEXT, "read");
    ssize_t r = real_read(fd, buf, n);
    if (fd >= 0 && fd < FD_CAP && read_fail_fd[fd] && r == 0) {
        errno = EIO;
        return -1;
    }
    return r;
}

int close(int fd) {
    if (!real_close) real_close = dlsym(RTLD_NEXT, "close");
    if (fd >= 0 && fd < FD_CAP) read_fail_fd[fd] = 0;
    return real_close(fd);
}
