 * 经过未介入的内部 close，留下过期缓存），这里都先清掉该 fd 的旧状态再
 * 重新分类，避免复用的 fd 沿用启动期（如读取 locale/ELF 时）的结论。 */
static void reclassify_fd(int fd) {
    if (fd < 0 || fd >= FD_CAP) return;
    g_state[fd] = 0;
    g_delivered[fd] = 0;
    g_fail_after[fd] = 0;
    classify_fd(fd);
}

